    {
      "finding_id": "F001",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "Rounding logic for negative amounts does not handle half values correctly; negative results are rounded towards zero instead of away from zero.",
      "evidence": "candidate.percent_of(-1, 50) == 0 but expected -1, because -1*50/100 = -0.5 should round to -1."
    }
  ]
}
